import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../api_client.dart';
import '../auth/session_controller.dart';

/// Normalizes a user-entered friend code by removing whitespace and uppercasing.
String normalizeFriendCode(String raw) =>
    raw.replaceAll(RegExp(r'\s+'), '').toUpperCase();

/// A short-lived friend code generated by `POST /api/v1/friends/code`.
@immutable
class FriendCode {
  const FriendCode({
    required this.code,
    required this.expiresAt,
  });

  final String code;
  final DateTime expiresAt;

  static FriendCode fromJson(Map<String, Object?> json) {
    final code = json['code'];
    final rawExpiry = json['expiresAt'];
    if (code is! String || code.isEmpty || rawExpiry == null) {
      throw const ApiException(500, 'invalid_response');
    }
    final DateTime expiresAt;
    if (rawExpiry is String) {
      expiresAt = DateTime.parse(rawExpiry);
    } else if (rawExpiry is num) {
      expiresAt = DateTime.fromMillisecondsSinceEpoch(rawExpiry.toInt());
    } else {
      throw const ApiException(500, 'invalid_response');
    }
    return FriendCode(code: code, expiresAt: expiresAt);
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FriendCode && code == other.code && expiresAt == other.expiresAt;

  @override
  int get hashCode => Object.hash(code, expiresAt);
}

/// Summary of a kid belonging to a friend family, as returned by
/// `GET /api/v1/friends` and `POST /api/v1/friends/redeem`.
@immutable
class FriendKid {
  const FriendKid({
    required this.kidUuid,
    required this.nickname,
    required this.avatar,
    required this.rocket,
  });

  final String kidUuid;
  final String nickname;
  final String avatar;
  final String rocket;

  static FriendKid fromJson(Map<String, Object?> json) {
    final kidUuid = json['kidUuid'];
    if (kidUuid is! String || kidUuid.isEmpty) {
      throw const ApiException(500, 'invalid_response');
    }
    final nickname = json['nickname'] as String? ?? '';
    final avatar = json['avatar'] as String? ?? '';
    final rawRocket = json['rocket'] as String?;
    final rocket =
        rawRocket != null && rawRocket.isNotEmpty ? rawRocket : 'rocket_orange';
    return FriendKid(
      kidUuid: kidUuid,
      nickname: nickname,
      avatar: avatar,
      rocket: rocket,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FriendKid &&
          kidUuid == other.kidUuid &&
          nickname == other.nickname &&
          avatar == other.avatar &&
          rocket == other.rocket;

  @override
  int get hashCode => Object.hash(kidUuid, nickname, avatar, rocket);
}

/// A connected friend family with its kids and live online flag.
@immutable
class FriendFamily {
  const FriendFamily({
    required this.familyId,
    required this.kids,
    this.online = false,
  });

  final String familyId;
  final List<FriendKid> kids;
  final bool online;

  FriendFamily copyWith({
    List<FriendKid>? kids,
    bool? online,
  }) =>
      FriendFamily(
        familyId: familyId,
        kids: kids ?? this.kids,
        online: online ?? this.online,
      );

  static FriendFamily fromJson(Map<String, Object?> json) {
    final familyId = json['familyId'];
    if (familyId is! String || familyId.isEmpty) {
      throw const ApiException(500, 'invalid_response');
    }
    final rawKids = json['kids'];
    final kids = <FriendKid>[];
    if (rawKids is List) {
      for (final item in rawKids) {
        if (item is Map) {
          kids.add(FriendKid.fromJson(item.cast<String, Object?>()));
        }
      }
    }
    return FriendFamily(
      familyId: familyId,
      kids: List.unmodifiable(kids),
      online: json['online'] == true,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FriendFamily &&
          familyId == other.familyId &&
          listEquals(kids, other.kids) &&
          online == other.online;

  @override
  int get hashCode =>
      Object.hash(familyId, Object.hashAll(kids), online);
}

typedef AuthorizedRunner = Future<T> Function<T>(
  Future<T> Function(String accessToken) call,
);

/// REST client for family-level race friendships (`/api/v1/friends`).
class FriendsApi {
  const FriendsApi(this._api, this._authorized);

  final ApiClient _api;
  final AuthorizedRunner _authorized;

  /// Generates a 6-character friend code valid for 24 hours.
  Future<FriendCode> createCode() async {
    final res = await _authorized(
      (t) => _api.post('/api/v1/friends/code', const {}, accessToken: t),
    );
    if (res == null) throw const ApiException(500, 'invalid_response');
    return FriendCode.fromJson(res);
  }

  /// Redeems another family's friend code and returns the added [FriendFamily].
  Future<FriendFamily> redeemCode(String code) async {
    final normalized = normalizeFriendCode(code);
    final res = await _authorized(
      (t) => _api.post(
        '/api/v1/friends/redeem',
        {'code': normalized},
        accessToken: t,
      ),
    );
    final rawFriend = res?['friend'];
    if (rawFriend is! Map) {
      throw const ApiException(500, 'invalid_response');
    }
    return FriendFamily.fromJson(rawFriend.cast<String, Object?>());
  }

  /// Lists all connected friend families and their kids.
  Future<List<FriendFamily>> listFriends() async {
    final res = await _authorized(
      (t) => _api.getList('/api/v1/friends', accessToken: t),
    );
    if (res == null) return const [];
    return [
      for (final item in res)
        if (item is Map)
          FriendFamily.fromJson(item.cast<String, Object?>()),
    ];
  }

  /// Removes the bidirectional friendship with [familyId].
  Future<void> removeFriend(String familyId) async {
    await _authorized(
      (t) => _api.delete('/api/v1/friends/$familyId', accessToken: t),
    );
  }
}

final friendsApiProvider = Provider<FriendsApi>(
  (ref) => FriendsApi(
    ref.watch(apiClientProvider),
    ref.read(sessionProvider.notifier).authorized,
  ),
);
